phase = 'FORWARD'
start_cov = None
prev_hitch = -0.4

def control(obs):
    global phase, start_cov, prev_hitch

    dt = obs.get('dt', 0.1)
    hitch_deg = obs.get('hitch_deg', 0.0)
    progress = obs.get('progress', {})
    cov = progress.get('covered', 17.3)

    if start_cov is None:
        start_cov = cov

    # Phase 1: Pull forward to clear the pinch point
    if phase == 'FORWARD':
        pulled_dist = start_cov - cov
        if pulled_dist < 1.8:
            prev_hitch = hitch_deg
            return {
                'steer_deg': -8.0,
                'speed_mps': 1.0,
                'look_deg': 64.0
            }
        else:
            phase = 'REVERSE'

    # Phase 2: Reverse through the bend
    if cov < 21.0:
        target_hitch = 8.0
    elif cov < 25.0:
        target_hitch = 2.0
    elif cov < 35.0:
        target_hitch = -8.0
    else:
        target_hitch = 0.0

    hitch_err = hitch_deg - target_hitch
    hitch_deriv = (hitch_deg - prev_hitch) / max(dt, 0.01)
    prev_hitch = hitch_deg

    steer_deg = 2.6 * hitch_err + 0.8 * hitch_deriv
    steer_deg = max(-35.0, min(35.0, steer_deg))

    look_target = 64.0 if (int(obs.get('t', 0.0) / 2.0) % 2 == 0) else -64.0

    return {
        'steer_deg': steer_deg,
        'speed_mps': -0.65,
        'look_deg': look_target
    }

