import math

phase = 'HOLD_PENALTY'
pull_dist = 0.0

def control(obs):
    global phase, pull_dist
    dt = obs.get('dt', 0.1)
    hold = obs.get('motion', {}).get('hold_s', 0.0)
    hitch = obs.get('hitch_deg', 0.0)
    status = obs.get('status', '')

    # In penalty or pinned
    if hold > 0.0 or status == 'PINNED':
        return {'steer_deg': 0.0, 'speed_mps': 0.0, 'look_deg': 0.0}

    if phase == 'HOLD_PENALTY':
        phase = 'PULL_FORWARD'
        pull_dist = 0.0

    if phase == 'PULL_FORWARD':
        v = obs.get('motion', {}).get('v_mps', 0.0)
        if v > 0.01:
            pull_dist += v * dt

        # Steer slightly left (+10) while driving forward to shift tractor/trailer rightward
        steer = 10.0
        speed = 0.5
        look = 0.0
        if pull_dist >= 1.5:
            phase = 'STABILIZE_FWD'
        return {'steer_deg': steer, 'speed_mps': speed, 'look_deg': look}

    if phase == 'STABILIZE_FWD':
        v = obs.get('motion', {}).get('v_mps', 0.0)
        if v > 0.01:
            pull_dist += v * dt
        steer = 0.0
        speed = 0.35
        look = 170.0
        if abs(hitch) < 1.0 or pull_dist >= 2.0:
            phase = 'REVERSE'
        return {'steer_deg': steer, 'speed_mps': speed, 'look_deg': look}

    # Phase REVERSE: reverse centering the trailer between rails
    look = 170.0
    views = obs.get('views', {})
    left_y_min = 999.0
    right_y_min = 999.0
    for vname, vdata in views.items():
        ox, oy = vdata.get('origin', [0, 0])
        walls = vdata.get('walls', [])
        for b_deg, d in walls:
            rad = math.radians(b_deg)
            wx = ox + d * math.cos(rad)
            wy = oy + d * math.sin(rad)
            if wx < 0.5:
                if wy > 0:
                    if wy < left_y_min:
                        left_y_min = wy
                else:
                    if abs(wy) < right_y_min:
                        right_y_min = abs(wy)

    target_hitch = 0.0
    if left_y_min < 50 and right_y_min < 50:
        target_hitch = (left_y_min - right_y_min) * 4.0
    elif left_y_min < 50:
        target_hitch = (left_y_min - 1.1) * 4.0
    elif right_y_min < 50:
        target_hitch = (1.1 - right_y_min) * 4.0

    target_hitch = max(-3.0, min(3.0, target_hitch))

    hitch_err = hitch - target_hitch
    steer = 1.5 * hitch_err
    steer = max(-18.0, min(18.0, steer))

    speed = -0.35
    return {'steer_deg': steer, 'speed_mps': speed, 'look_deg': look}

