def control(obs):
    global t_start, mode

    t = obs['t']
    if t_start is None:
        t_start = t

    look_deg = obs['rig'].get('screen_gaze_deg', -41.0) or -41.0
    hitch = obs['hitch_deg']
    dt_elapsed = t - t_start

    if mode == 'pulling_forward':
        if dt_elapsed < 14.0:
            return {
                'steer_deg': 0.0,
                'speed_mps': 1.5,
                'look_deg': look_deg
            }
        else:
            mode = 'reversing'

    views = obs.get('views', {})
    camera = views.get('camera')

    left_dist = 999.0
    right_dist = 999.0

    if camera and 'walls' in camera:
        for b_deg, d in camera['walls']:
            rad = math.radians(b_deg)
            y_offset = d * math.sin(rad)
            if y_offset > 0 and d < left_dist:
                left_dist = min(left_dist, d)
            elif y_offset < 0 and d < right_dist:
                right_dist = min(right_dist, d)

    desired_hitch = -10.0

    if left_dist < 2.5:
        desired_hitch -= (2.5 - left_dist) * 6.0
    if right_dist < 2.2:
        desired_hitch += (2.2 - right_dist) * 6.0

    desired_hitch = max(-22.0, min(10.0, desired_hitch))

    kp = 2.0
    steer = kp * (hitch - desired_hitch)
    steer = max(-35.0, min(35.0, steer))

    return {
        'steer_deg': steer,
        'speed_mps': -1.0,
        'look_deg': look_deg
    }

